window.VeilGardeData.files["Tests-VeilGardeCoreTests"] = {"group":"Tests-VeilGardeCoreTests","files":[{"path":"Tests/VeilGardeCoreTests/BoostTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,52]],"header":{"lines":[1,9],"target":"VeilGardeCoreTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1298,"scopes":[["S","BoostTests",null,"",15,16,[16,18],52,null,-1,0,"a"],["f","byteIdentity",[],"",17,18,[18,31],23,null,0,0,"a"],["f","cameraShape",[],"",25,26,[26,30],31,null,0,0,"a"],["f","freshModel",[],"",33,34,[34,29],51,null,0,0,"a"]],"old":"","new":"//\n//  BoostTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: GBDTModel against the shipped camera head: decoding then encoding writes the file's exact\n//        bytes; the head is a from-scratch fit over the 393-column camera row; a fresh model encodes and\n//        decodes to itself. (The trainer's parity with xgboost 3.2 is BoostTrainerTests'.)\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Boost codec and evaluator\")\nstruct BoostTests {\n    @Test(\"the shipped camera head round-trips to its exact bytes\")\n    func byteIdentity() throws {\n        let data = try Data(contentsOf: Fixture.resource(\"camera.xgb.json\"))\n        let model = try GBDTModel.decode(xgboostJSON: data)\n        let encoded = model.encodeXGBoostJSON()\n        #expect(encoded == data, \"\\(encoded.count) bytes vs \\(data.count)\")\n    }\n\n    @Test(\"the shipped camera head is 500 trees of depth at most 5 over the 393-column camera row\")\n    func cameraShape() throws {\n        let head = try GBDTModel.load(Fixture.resource(\"camera.xgb.json\"))\n        #expect(head.trees.count == 500)\n        #expect(head.featureCount == CameraRow.width && CameraRow.width == 393)\n        #expect((head.trees.map(\\.depth).max() ?? 0) <= 5)\n    }\n\n    @Test(\"a fresh model encodes, decodes and predicts as built\")\n    func freshModel() throws {\n        // root: x0 < 0.5 → leaf −0.2, else x1 < 1 → leaf 0.1 | leaf 0.3\n        let tree = GBDTModel.Tree(id: 0, leftChildren: [1, -1, 3, -1, -1], rightChildren: [2, -1, 4, -1, -1],\n                                  parents: [GBDTModel.Tree.rootParent, 0, 0, 2, 2], splitIndices: [0, 0, 1, 0, 0],\n                                  splitConditions: [0.5, -0.2, 1, 0.1, 0.3], baseWeights: [0.01, -0.2, 0.05, 0.1, 0.3],\n                                  defaultLeft: [0, 0, 0, 0, 0], splitType: [0, 0, 0, 0, 0], lossChanges: [3, 0, 1.5, 0, 0],\n                                  sumHessian: [10, 4, 6, 3, 3], numFeature: 2)\n        let model = GBDTModel(trees: [tree], baseScoreProbability: 0.25, featureCount: 2)\n        let decoded = try GBDTModel.decode(xgboostJSON: model.encodeXGBoostJSON())\n        #expect(decoded.trees.count == 1)\n        #expect(decoded.trees[0].splitConditions == tree.splitConditions)\n        #expect(decoded.featureCount == 2)\n        #expect(decoded.encodeXGBoostJSON() == model.encodeXGBoostJSON())\n        let logit = Float(log(0.25 / 0.75))\n        #expect(abs(decoded.margin([0.2, 0]) - (logit - 0.2)) < 1e-6)\n        #expect(abs(decoded.margin([0.9, 2]) - (logit + 0.3)) < 1e-6)\n        #expect(decoded.margin([0.9]) == decoded.margin([0.9, 0]))   // a missing column reads 0\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/BundleTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,49]],"header":{"lines":[1,9],"target":"VeilGardeCoreTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1302,"scopes":[["S","BundleTests",null,"",15,16,[16,19],49,null,-1,0,"a"],["f","shippedBundleVerifies",[],"",17,18,[18,40],28,null,0,0,"a"],["f","tamperRefused",[],"",30,31,[31,32],41,null,0,0,"a"],["f","frozenRoles",[],"",43,44,[44,23],48,null,0,0,"a"]],"old":"","new":"//\n//  BundleTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The shipped bundle is exactly the bytes its manifest names (the camera head and the\n//        combiner trained here on 2026-10-21, six heads); a moved file is refused; the frozen roles\n//        are the weights, which the flywheel may never promote over.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Bundle manifest\")\nstruct BundleTests {\n    @Test(\"the shipped bundle's manifest verifies every artifact\")\n    func shippedBundleVerifies() throws {\n        let bundle = try ModelBundle.load(Fixture.resources)\n        #expect(bundle.manifest.artifacts.count == 8)\n        #expect(bundle.manifest.weights.count == 3)\n        #expect(bundle.sha256(.camera) == \"b142e661c609070a7838fb015ae47a8b9ccce2ab1d539c3dac29afadc48b8f9e\")\n        #expect(bundle.manifest.artifact(.camera)?.file == \"camera.xgb.json\" && bundle.manifest.artifact(.combiner)?.file == \"stack_combiner.json\")\n        #expect(bundle.sha256(.combiner) == ContentHash.sha256Hex(try Data(contentsOf: Fixture.resource(\"stack_combiner.json\"))))\n        #expect(bundle.manifest.artifact(.camera)?.parent == nil, \"a scratch fit continues no parent\")\n        for head in HeadKind.allCases { #expect(bundle.url(.head, head: head) != nil, \"no \\(head.rawValue) head\") }\n        #expect(bundle.manifest.history.map(\\.kind) == [.seed] && bundle.manifest.history.first?.slot == \"bundle\", \"v1 starts its history fresh\")\n    }\n\n    @Test(\"a file that moved under its manifest is refused\")\n    func tamperRefused() throws {\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-bundle-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n        defer { try? FileManager.default.removeItem(at: dir) }\n        try Data(\"{}\".utf8).write(to: dir.appendingPathComponent(\"a.json\"))\n        let manifest = BundleManifest(artifacts: [try ModelBundle.record(.combiner, file: \"a.json\", in: dir)])\n        try JSONCoding.write(manifest, to: dir.appendingPathComponent(BundleManifest.fileName))\n        _ = try ModelBundle.load(dir)\n        try Data(\"{ }\".utf8).write(to: dir.appendingPathComponent(\"a.json\"))\n        #expect(throws: VeilGardeFailure.self) { try ModelBundle.load(dir) }\n    }\n\n    @Test(\"frozen roles are the weights\")\n    func frozenRoles() {\n        let frozen = Set(ArtifactRole.allCases.filter(\\.isFrozen))\n        #expect(frozen == [.dinov2Small, .dinov2XSmall, .dinov2XXSmall, .clipVision])\n        #expect(!ArtifactRole.camera.isFrozen && !ArtifactRole.head.isFrozen && !ArtifactRole.combiner.isFrozen)\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,37]],"header":{"lines":[1,8],"target":"VeilGardeCoreTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1306,"scopes":[["E","Fixture",null,"",13,13,[13,13],34,null,-1,0,"a",[]],["f","resource",["_"],"static",22,22,[22,48],22,null,0,8,"a"],["f","url",["_"],"static",24,24,[24,43],24,null,0,8,"a"],["f","json",["_"],"static",26,26,[26,61],28,null,0,0,"a"],["f","floats",["_"],"",36,36,[36,36],36,null,-1,8,"a"],["f","float",["_"],"",37,37,[37,34],37,null,-1,8,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the Core tests read: their committed fixtures (written once from the Python\n//        reference) and the shipped bundle's resources, both by repo path.\n//\n\nimport Foundation\nimport VeilGardeCore\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static let resources = repoRoot.appendingPathComponent(\"Sources/VeilGardeInference/Resources\")\n\n    static func resource(_ name: String) -> URL { resources.appendingPathComponent(name) }\n\n    static func url(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeCoreTests/Fixtures/\\(name)\") }\n\n    static func json(_ name: String) throws -> [String: Any] {\n        try JSONSerialization.jsonObject(with: Data(contentsOf: url(name))) as! [String: Any]\n    }\n\n    /// The work area's feature store, when this Mac has it (the Store suite reads one small shard\n    /// from it); VEILGARDE_SEED_STORE names another.\n    static let seedStore = URL(fileURLWithPath: ProcessInfo.processInfo.environment[\"VEILGARDE_SEED_STORE\"]\n        ?? WorkArea.resolve()?.shards.path ?? \"store/shards\")\n}\n\nfunc floats(_ any: Any?) -> [Float] { (any as? [NSNumber])?.map { $0.floatValue } ?? [] }\nfunc float(_ any: Any?) -> Float? { (any as? NSNumber)?.floatValue }\n"},{"path":"Tests/VeilGardeCoreTests/HeadsTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,103]],"header":{"lines":[1,10],"target":"VeilGardeCoreTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1312,"scopes":[["S","HeadsTests",null,"",16,17,[17,18],103,null,-1,0,"a"],["f","linearHead",[],"",18,19,[19,29],28,null,0,0,"a"],["f","shippedHeads",["file"],"",34,34,[34,43],37,null,0,0,"a"],["f","headFile",[],"",39,40,[40,27],47,null,0,0,"a"],["f","combinerWeights",[],"",49,50,[50,34],58,null,0,0,"a"],["f","otherVersionRefused",[],"",60,61,[61,38],73,null,0,0,"a"],["f","combinerArithmetic",[],"",75,76,[76,37],92,null,0,0,"a"],["f","combinerFile",[],"",94,95,[95,31],102,null,0,0,"a"]],"old":"","new":"//\n//  HeadsTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The linear head and the stack combiner against float32 replicas of the reference's\n//        arithmetic (written once from the Python reference), the shipped combiner as fitted on\n//        2026-10-21 and keyed by member, a combiner file of another version refused, and the\n//        trainer's file forms loading back as the runtime types.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Heads and combiner\")\nstruct HeadsTests {\n    @Test(\"the art head's P(AI) matches the float32 replica\")\n    func linearHead() throws {\n        let reference = try Fixture.json(\"head_reference.json\")\n        let head = try LinearHead.load(Fixture.resource(\"art_dinov2_v2.json\"))\n        #expect(head.coef.count == 384)\n        #expect(head.normW == 360 && head.normH == 640)\n        for case let c as [String: Any] in reference[\"cases\"] as! [Any] {\n            let p = head.pAI(floats(c[\"embedding\"]))\n            #expect(abs(p - float(c[\"p\"])!) < 1e-6)\n        }\n    }\n\n    @Test(\"every shipped head decodes with 384 coefficients\", arguments: [\n        \"screenshot_dinov2_v1.10.json\", \"art_dinov2_v2.json\", \"blur_dinov2_v1.json\", \"human_dinov2_v4.json\",\n        \"semtile_dinov2_v1.json\", \"preview_dinov2_v1.json\",\n    ])\n    func shippedHeads(file: String) throws {\n        let head = try LinearHead.load(Fixture.resource(file))\n        #expect(head.coef.count == 384 && head.mean.count == 384 && head.scale.count == 384)\n    }\n\n    @Test(\"a HeadFile written by the trainer loads as the head it describes\")\n    func headFile() throws {\n        let file = HeadFile(model: \"test_dinov2\", scalerMean: [0, 1], scalerScale: [1, 2], coef: [0.5, -0.25], intercept: 0.1)\n        let head = try file.linearHead()\n        let z: Float = 0.1 + 0.5 * 1 + ((3 - 1) / 2) * -0.25\n        #expect(abs(head.pAI([1, 3]) - 1 / (1 + exp(-z))) < 1e-7)\n        let text = String(decoding: try JSONCoding.prettyEncoder().encode(file), as: UTF8.self)\n        #expect(text.contains(\"\\\"scaler_mean\\\"\") && text.contains(\"\\\"fire_threshold\\\"\") && text.contains(\"\\\"embed_source\\\"\"))\n    }\n\n    @Test(\"the shipped combiner is the 2026-10-21 fit, keyed by member: the camera anchor, art, blur and human as evidence\")\n    func combinerWeights() throws {\n        let c = try StackCombiner.load(Fixture.resource(\"stack_combiner.json\"))\n        #expect(c.model == \"stack_combiner\" && c.version == 1)\n        #expect(abs(c.w0 - -1.0216338510927914) < 1e-6)\n        #expect(abs(c.anchor.w - 1.664112977699542) < 1e-6 && c.anchor.cap == 4 && c.anchor.gateCeiling == 0.75)\n        #expect(c.evidenceMembers == [\"art\", \"blur\", \"human\"])\n        #expect(abs(c.evidence[0].w - 0.15331665321009014) < 1e-6 && abs(c.evidence[1].w - 0.2197897549987958) < 1e-6 && abs(c.evidence[2].w - 0.2999066044320255) < 1e-6)\n        #expect(c.rescue.w == 1 && c.evidenceCap == 2)\n    }\n\n    @Test(\"a combiner file of another version or model is refused\")\n    func otherVersionRefused() throws {\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-combiner-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n        defer { try? FileManager.default.removeItem(at: dir) }\n        let old = dir.appendingPathComponent(\"old.json\")\n        try Data(#\"{\"model\": \"stack_combiner\", \"version\": 3, \"w0\": 0, \"w_base\": 1, \"w_gen\": [0, 0, 0], \"w_rescue\": 0.5, \"cap_base\": 4, \"cap_head\": 2, \"gate_ceiling\": 0.75}\"#.utf8).write(to: old)\n        #expect(throws: VeilGardeFailure.self) { try StackCombiner.load(old) }\n        var other = try JSONSerialization.jsonObject(with: Data(contentsOf: Fixture.resource(\"stack_combiner.json\"))) as! [String: Any]\n        other[\"version\"] = 2\n        let next = dir.appendingPathComponent(\"next.json\")\n        try JSONSerialization.data(withJSONObject: other).write(to: next)\n        #expect(throws: VeilGardeFailure.self) { try StackCombiner.load(next) }\n    }\n\n    @Test(\"pool and contribution match the float32 replica on the 19 tuples no art-pair moved\")\n    func combinerArithmetic() throws {\n        let reference = try Fixture.json(\"combiner_reference.json\")\n        let c = try StackCombiner.load(Fixture.url(\"combiner_research.json\"))\n        var checked = 0\n        for case let t as [String: Any] in reference[\"cases\"] as! [Any] {\n            let anchor = float(t[\"base\"])!, evidence = floats(t[\"heads\"])\n            // The replica's art logit was min(art, art-pair); the cases where the pair moved it left with the art-pair head.\n            if let pair = float(t[\"pair\"]), c.lg(pair, c.evidenceCap) < c.lg(evidence[0], c.evidenceCap) { continue }\n            checked += 1\n            #expect(abs(c.pool(anchor: anchor, evidence: evidence) - float(t[\"pool\"])!) < 1e-6)\n            let expected = floats(t[\"contribution\"])\n            for k in 0..<3 { #expect(abs(c.contribution(k, anchor: anchor, evidence: evidence) - expected[k]) < 1e-6) }\n        }\n        #expect(checked == 19)\n        // Neutral evidence at an even anchor: only w0 speaks.\n        #expect(abs(c.pool(anchor: 0.5, evidence: [0.5, 0.5, 0.5]) - 1 / (1 + exp(0.6754975))) < 1e-6)\n    }\n\n    @Test(\"a CombinerFile loads as the combiner it describes\")\n    func combinerFile() throws {\n        let file = CombinerFile(w0: -0.5, anchor: .init(w: 3), evidence: [.init(member: \"art\", w: 0), .init(member: \"blur\", w: 0.1), .init(member: \"human\", w: 0.2)],\n                                rescue: .init(w: 0.5), note: \"test\")\n        let c = try file.combiner()\n        #expect(c.evidence.map(\\.w) == [0, 0.1, 0.2] && c.evidenceMembers == [\"art\", \"blur\", \"human\"] && c.anchor.gateCeiling == 0.75 && c.version == 1)\n        let text = String(decoding: try JSONCoding.prettyEncoder().encode(file), as: UTF8.self)\n        #expect(text.contains(\"\\\"evidence_cap\\\"\") && text.contains(\"\\\"gate_ceiling\\\"\") && !text.contains(\"w_base\"))\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/PackageLayeringTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,275]],"header":{"lines":[1,13],"target":"VeilGardeCoreTests","what":[6,12],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1320,"scopes":[["f","text",["_"],"private",27,27,[27,55],29,null,-1,0,"a"],["f","swiftFiles",["under"],"private",31,31,[31,57],37,null,-1,0,"a"],["S","ManifestTarget",null,"private",40,40,[40,30],45,[39,39],-1,0,"a"],["f","manifestTargets",[],"private",47,47,[47,58],79,null,-1,0,"a"],["f","module",["ofProduct"],"private",82,82,[82,57],82,[81,81],-1,8,"a"],["f","imports",["in"],"private",95,95,[95,50],103,null,-1,0,"a"],["S","PackageLayeringTests",null,"",105,106,[106,28],275,null,-1,0,"a"],["f","products",[],"",119,120,[120,27],128,null,6,0,"a"],["f","layerTable",[],"",130,131,[131,29],137,null,6,0,"a"],["f","mlxThroughFrigate",[],"",139,140,[140,36],150,null,6,0,"a"],["f","importsAreDeclared",[],"",152,153,[153,37],186,null,6,0,"a"],["f","closure",["_"],"",156,156,[156,52],166,null,10,4,"a"],["f","noForbiddenImports",[],"",188,189,[189,37],200,null,6,0,"a"],["f","noFrigateReimplementation",[],"",202,203,[203,44],219,null,6,0,"a"],["f","names",[],"",221,222,[222,24],233,null,6,0,"a"],["f","bundleModuleInOneFile",[],"",235,236,[236,40],243,null,6,0,"a"],["f","headers",[],"",245,246,[246,26],256,null,6,0,"a"],["f","licenses",[],"",258,259,[259,27],274,null,6,0,"a"]],"old":"","new":"//\n//  PackageLayeringTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The manifest and the sources to the package's rules, as text over Package.swift,\n//        Sources/, Tests/ and Examples/: exactly four products; the layer table (which target\n//        may depend on which); MLX only through Frigate, each Frigate module imported only by a\n//        target that lists its product; Core on Foundation and Crypto alone; nothing imports\n//        MLXLLM, MLXLMCommon, AppKit or UIKit; nothing re-declares a Frigate function; no type is\n//        named like a module; Bundle.module in one file; every Swift file opens with its name, its\n//        target, its license and its WHAT; every script, manifest and site script names GPL-3.0.\n//\n\nimport Foundation\nimport Testing\n\nprivate let repoRoot: URL = {\n    var url = URL(fileURLWithPath: #filePath)\n    while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n    return url.deletingLastPathComponent()\n}()\n\n/// The identifier every source file carries (LICENSE holds the text).\nprivate let license = \"SPDX-License-Identifier: GPL-3.0-only\"\n\nprivate func text(_ relative: String) throws -> String {\n    try String(contentsOf: repoRoot.appendingPathComponent(relative), encoding: .utf8)\n}\n\nprivate func swiftFiles(under relative: String) -> [URL] {\n    let root = repoRoot.appendingPathComponent(relative)\n    guard let walker = FileManager.default.enumerator(at: root, includingPropertiesForKeys: nil) else { return [] }\n    return walker.compactMap { $0 as? URL }\n        .filter { $0.pathExtension == \"swift\" && !$0.path.contains(\"/.build/\") && !$0.path.contains(\"/.work/\") && !$0.lastPathComponent.hasPrefix(\"._\") }\n        .sorted { $0.path < $1.path }\n}\n\n/// One `.target(`, `.executableTarget(` or `.testTarget(` block of the manifest, read as text.\nprivate struct ManifestTarget {\n    var name: String\n    var kind: String\n    var targets: Set<String>\n    var products: Set<String>\n}\n\nprivate func manifestTargets() throws -> [ManifestTarget] {\n    let manifest = try text(\"Package.swift\")\n    let opener = try NSRegularExpression(pattern: #\"\\.(target|executableTarget|testTarget)\\(\\s*name:\\s*\"(\\w+)\"\"#)\n    let product = try NSRegularExpression(pattern: #\"\\.product\\(name:\\s*\"(\\w+)\",\\s*package:\\s*\"([\\w-]+)\"\\)\"#)\n    let quoted = try NSRegularExpression(pattern: #\"\"(\\w+)\"\"#)\n    let ns = manifest as NSString\n    let matches = opener.matches(in: manifest, range: NSRange(location: 0, length: ns.length))\n    var result: [ManifestTarget] = []\n    for (i, match) in matches.enumerated() {\n        let end = i + 1 < matches.count ? matches[i + 1].range.location : ns.length\n        let block = ns.substring(with: NSRange(location: match.range.location, length: end - match.range.location))\n        let kind = ns.substring(with: match.range(at: 1))\n        let name = ns.substring(with: match.range(at: 2))\n        var dependencies = \"\"\n        if let start = block.range(of: \"dependencies:\") {\n            let rest = block[start.upperBound...]\n            if let close = rest.firstIndex(of: \"]\") { dependencies = String(rest[..<close]) }\n        }\n        let depNS = dependencies as NSString\n        var products: Set<String> = []\n        for found in product.matches(in: dependencies, range: NSRange(location: 0, length: depNS.length)) {\n            products.insert(depNS.substring(with: found.range(at: 1)))\n        }\n        let stripped = product.stringByReplacingMatches(in: dependencies, range: NSRange(location: 0, length: depNS.length), withTemplate: \"\")\n        let strippedNS = stripped as NSString\n        var targets: Set<String> = []\n        for found in quoted.matches(in: stripped, range: NSRange(location: 0, length: strippedNS.length)) {\n            targets.insert(strippedNS.substring(with: found.range(at: 1)))\n        }\n        result.append(ManifestTarget(name: name, kind: kind, targets: targets, products: products))\n    }\n    return result\n}\n\n/// The module a Frigate product builds (they share a name except the hub).\nprivate func module(ofProduct product: String) -> String { product == \"FrigateHub\" ? \"Hub\" : product }\n\nprivate let frigateModules: Set<String> = [\n    \"Frigate\", \"MLX\", \"MLXNN\", \"MLXFFT\", \"MLXAccelerate\", \"MLXOptimizers\", \"MLXRandom\", \"MLXLinalg\", \"MLXFast\",\n    \"Hub\", \"Tokenizers\", \"MLXLLM\", \"MLXVLM\", \"MLXLMCommon\", \"MLXEmbedders\", \"FrigateBridge\", \"FrigateParallel\",\n]\n\nprivate let systemModules: Set<String> = [\n    \"Foundation\", \"Dispatch\", \"Darwin\", \"CoreGraphics\", \"ImageIO\", \"UniformTypeIdentifiers\", \"CoreFoundation\", \"os\", \"AppKit\",\n    // Apple's Accelerate (CPU BLAS for the linear solvers), not Frigate's MLX-backed MLXAccelerate.\n    \"Accelerate\",\n]\n\nprivate func imports(in body: String) -> [String] {\n    body.split(separator: \"\\n\").compactMap { line in\n        let trimmed = line.trimmingCharacters(in: .whitespaces)\n        for prefix in [\"@_exported import \", \"@testable import \", \"import \"] where trimmed.hasPrefix(prefix) {\n            return String(trimmed.dropFirst(prefix.count).split(separator: \" \").first ?? \"\")\n        }\n        return nil\n    }\n}\n\n@Suite(\"Package layering\")\nstruct PackageLayeringTests {\n    /// Who may depend on whom. A new edge is a design change: change this table on purpose.\n    static let layers: [String: Set<String>] = [\n        \"VeilGardeCore\": [],\n        \"VeilGardeLens\": [\"VeilGardeCore\"],\n        \"VeilGardeInference\": [\"VeilGardeLens\"],\n        \"VeilGardeTraining\": [\"VeilGardeLens\"],\n        \"VeilGardeFlywheel\": [\"VeilGardeTraining\", \"VeilGardeInference\"],\n        \"VeilWatermark\": [\"VeilGardeLens\"],\n        \"VeilGarde\": [\"VeilGardeInference\", \"VeilGardeTraining\", \"VeilGardeFlywheel\", \"VeilWatermark\"],\n        \"VeilGardeCLI\": [\"VeilGarde\"],\n    ]\n\n    @Test(\"four products: VeilGarde, VeilGardeInference, VeilWatermark and the veilgarde executable\")\n    func products() throws {\n        let manifest = try text(\"Package.swift\")\n        #expect(manifest.contains(\".library(name: \\\"VeilGarde\\\"\"))\n        #expect(manifest.contains(\".library(name: \\\"VeilGardeInference\\\"\"))\n        #expect(manifest.contains(\".library(name: \\\"VeilWatermark\\\"\"))\n        #expect(manifest.contains(\".executable(name: \\\"veilgarde\\\"\"))\n        #expect(manifest.components(separatedBy: \".library(name:\").count == 4)\n        #expect(manifest.components(separatedBy: \".executable(name:\").count == 2)\n    }\n\n    @Test(\"the source targets and their edges are the layer table\")\n    func layerTable() throws {\n        let sources = try manifestTargets().filter { $0.kind != \"testTarget\" }\n        #expect(Set(sources.map(\\.name)) == Set(Self.layers.keys))\n        for target in sources {\n            #expect(target.targets == Self.layers[target.name], \"\\(target.name) depends on \\(target.targets.sorted())\")\n        }\n    }\n\n    @Test(\"MLX comes only from Frigate: no mlx-swift package, Frigate taken by path\")\n    func mlxThroughFrigate() throws {\n        let manifest = try text(\"Package.swift\")\n        let url = try NSRegularExpression(pattern: #\"\\.package\\(url:\\s*\"([^\"]+)\"\"#)\n        let ns = manifest as NSString\n        let urls = url.matches(in: manifest, range: NSRange(location: 0, length: ns.length)).map { ns.substring(with: $0.range(at: 1)) }\n        #expect(!urls.isEmpty)\n        for found in urls {\n            #expect(!found.contains(\"ml-explore\") && !found.contains(\"mlx\"), \"Package.swift takes \\(found) by URL\")\n        }\n        #expect(manifest.contains(\".package(path: frigate)\"))\n    }\n\n    @Test(\"every import sits inside its target's declared dependencies\")\n    func importsAreDeclared() throws {\n        let targets = try manifestTargets()\n        let byName = Dictionary(uniqueKeysWithValues: targets.map { ($0.name, $0) })\n        func closure(_ name: String) -> Set<String> {\n            var seen: Set<String> = []\n            var stack = [name]\n            while let next = stack.popLast() {\n                for dependency in byName[next]?.targets ?? [] where !seen.contains(dependency) {\n                    seen.insert(dependency)\n                    stack.append(dependency)\n                }\n            }\n            return seen\n        }\n        for target in targets where target.kind != \"testTarget\" {\n            let directProducts = Set(target.products.map(module(ofProduct:)))\n            let layer = closure(target.name)\n            let allowedSystem = target.name == \"VeilGardeCore\" ? [\"Foundation\", \"Crypto\"] : systemModules.union([\"Crypto\"])\n            for file in swiftFiles(under: \"Sources/\\(target.name)\") {\n                let body = try String(contentsOf: file, encoding: .utf8)\n                for name in imports(in: body) {\n                    if frigateModules.contains(name) {\n                        #expect(directProducts.contains(name), \"\\(target.name)/\\(file.lastPathComponent) imports \\(name) without listing its Frigate product\")\n                    } else if name.hasPrefix(\"VeilGarde\") || name == \"VeilWatermark\" {\n                        #expect(layer.contains(name), \"\\(target.name)/\\(file.lastPathComponent) imports \\(name), above its layer\")\n                    } else if name == \"ArgumentParser\" {\n                        #expect(target.name == \"VeilGardeCLI\", \"\\(file.lastPathComponent) imports ArgumentParser outside the CLI\")\n                    } else {\n                        #expect(allowedSystem.contains(name), \"\\(target.name)/\\(file.lastPathComponent) imports \\(name)\")\n                    }\n                }\n            }\n        }\n    }\n\n    @Test(\"nothing imports MLXLLM, MLXLMCommon, UIKit or SwiftUI, and AppKit only to decode images\")\n    func noForbiddenImports() throws {\n        for file in swiftFiles(under: \"Sources\") + swiftFiles(under: \"Examples/Sources\") {\n            let names = Set(imports(in: try String(contentsOf: file, encoding: .utf8)))\n            for forbidden in [\"MLXLLM\", \"MLXLMCommon\", \"UIKit\", \"SwiftUI\"] {\n                #expect(!names.contains(forbidden), \"\\(file.lastPathComponent) imports \\(forbidden)\")\n            }\n            // NSImage is the decoder every shipped artifact was computed through (ImageDecoding's PIN).\n            if names.contains(\"AppKit\") {\n                #expect(file.path.hasSuffix(\"Sources/VeilGardeLens/Image/ImageDecoding.swift\"), \"\\(file.lastPathComponent) imports AppKit\")\n            }\n        }\n    }\n\n    @Test(\"nothing re-declares a function Frigate already provides\")\n    func noFrigateReimplementation() throws {\n        let frigateFunctions = [\n            \"perspectiveWarp\", \"getPerspectiveTransform\", \"getPerspectiveTransformD\", \"invertMatrix3x3\", \"invertMatrix3x3D\",\n            \"gaussianBlur\", \"sobelGradients\", \"filter2D\", \"batchedFilter2D\", \"batchedSobelGradients\", \"batchedGaussianBlur\",\n            \"reflect101Index\", \"reflectPad101\", \"buildBicubicWarpTapsHost\", \"buildBicubicWarpTable\", \"applyWarpTable\",\n            \"spectralDistance\", \"kmeans\", \"nearestCentroids\", \"pairwiseSquaredDistances\", \"centroidDistanceTable\", \"gaussianElimination\",\n        ]\n        let declaration = try NSRegularExpression(pattern: #\"\\bfunc\\s+(\\w+)\\s*[(<]\"#)\n        for file in swiftFiles(under: \"Sources\") {\n            let body = try String(contentsOf: file, encoding: .utf8)\n            let ns = body as NSString\n            for match in declaration.matches(in: body, range: NSRange(location: 0, length: ns.length)) {\n                let name = ns.substring(with: match.range(at: 1))\n                #expect(!frigateFunctions.contains(name), \"\\(file.lastPathComponent) declares \\(name), which Frigate provides\")\n            }\n        }\n    }\n\n    @Test(\"no type is named like a module\")\n    func names() throws {\n        let modules = Set(Self.layers.keys).union(frigateModules).union([\"Crypto\", \"ArgumentParser\"])\n        let declaration = try NSRegularExpression(pattern: #\"\\b(struct|class|enum|actor|protocol|typealias)\\s+(\\w+)\"#)\n        for file in swiftFiles(under: \"Sources\") {\n            let body = try String(contentsOf: file, encoding: .utf8)\n            let ns = body as NSString\n            for match in declaration.matches(in: body, range: NSRange(location: 0, length: ns.length)) {\n                let name = ns.substring(with: match.range(at: 2))\n                #expect(!modules.contains(name), \"\\(file.lastPathComponent) declares a type named \\(name)\")\n            }\n        }\n    }\n\n    @Test(\"Bundle.module is written in two files: the shipped bundle and the flywheel's resources\")\n    func bundleModuleInOneFile() throws {\n        for file in swiftFiles(under: \"Sources\") {\n            let body = try String(contentsOf: file, encoding: .utf8)\n            guard body.contains(\"Bundle.module\") else { continue }\n            #expect(file.path.hasSuffix(\"Sources/VeilGardeInference/Bundle/ShippedBundle.swift\") || file.path.hasSuffix(\"Sources/VeilGardeFlywheel/FlywheelResources.swift\"),\n                    \"\\(file.lastPathComponent) reads Bundle.module\")\n        }\n    }\n\n    @Test(\"every Swift file opens with its name, its target, its license and a WHAT\")\n    func headers() throws {\n        for root in [\"Sources\", \"Tests\", \"Examples/Sources\"] {\n            for file in swiftFiles(under: root) {\n                let body = try String(contentsOf: file, encoding: .utf8)\n                let target = file.deletingLastPathComponent().pathComponents\n                    .drop { $0 != (root == \"Examples/Sources\" ? \"Sources\" : root) }.dropFirst().first ?? \"\"\n                let header = \"//\\n//  \\(file.lastPathComponent)\\n//  \\(target)\\n//  \\(license)\\n//\\n//  WHAT:\"\n                #expect(body.hasPrefix(header), \"\\(file.path.replacingOccurrences(of: repoRoot.path + \"/\", with: \"\")) does not open with its WHAT header\")\n            }\n        }\n    }\n\n    @Test(\"the manifests, every script and the site's code name the GPL-3.0 at the top\")\n    func licenses() throws {\n        for manifest in [\"Package.swift\", \"Examples/Package.swift\"] {\n            let lines = try text(manifest).split(separator: \"\\n\", omittingEmptySubsequences: false)\n            #expect(lines.count > 1 && lines[1] == \"// \\(license)\", \"\\(manifest) names its license on its second line\")\n        }\n        var scripts: [String] = [\"build-metallib.sh\", \"Examples/run.sh\"]\n        for folder in [\"scripts\", \"docs/site/src\", \"docs/site/js\"] {\n            let names = (try? FileManager.default.contentsOfDirectory(atPath: repoRoot.appendingPathComponent(folder).path)) ?? []\n            scripts += names.filter { !$0.hasPrefix(\".\") && [\"sh\", \"py\", \"js\", \"command\"].contains(URL(fileURLWithPath: $0).pathExtension) }.map { \"\\(folder)/\\($0)\" }\n        }\n        #expect(scripts.count >= 13)\n        for script in scripts.sorted() {\n            let top = try text(script).split(separator: \"\\n\", omittingEmptySubsequences: false).prefix(16)\n            #expect(top.contains { $0.hasSuffix(license) }, \"\\(script) names its license near the top\")\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/ResultJSONTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,126]],"header":{"lines":[1,10],"target":"VeilGardeCoreTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1338,"scopes":[["f","object",["_"],"private",16,16,[16,58],18,null,-1,0,"a"],["f","result",["bundle"],"private",32,32,[32,71],35,null,-1,0,"a"],["S","ResultJSONTests",null,"",37,38,[38,23],97,null,-1,0,"a"],["f","jsonV1",[],"",39,40,[40,25],50,null,2,0,"a"],["f","membersAndRevisions",[],"",52,53,[53,38],64,null,2,0,"a"],["f","jsonOmitsBundle",[],"",66,67,[67,34],72,null,2,0,"a"],["f","accessors",[],"",74,75,[75,21],79,null,2,0,"a"],["f","semanticProfiles",[],"",81,82,[82,28],89,null,2,0,"a"],["f","rawValues",[],"",91,92,[92,28],96,null,2,0,"a"],["S","RouteBatchTests",null,"",99,100,[100,23],126,null,-1,0,"a"],["f","parses",[],"",101,102,[102,25],108,null,9,0,"a"],["f","duplicate",[],"",110,111,[111,21],118,null,9,0,"a"],["f","rejects",[],"",120,121,[121,19],125,null,9,0,"a"]],"old":"","new":"//\n//  ResultJSONTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The result and its schema-v1 JSON: the JSON writes exactly the v1 keys, a member as its\n//        name, p and verdict beside its own fields, a revision as its name, applied, p and\n//        prediction beside its own, and the same result as the same bytes; only `.control`\n//        commits a semantic probe; the strict batch manifest.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\nprivate func object(_ data: Data) throws -> [String: Any] {\n    try #require(JSONSerialization.jsonObject(with: data) as? [String: Any])\n}\n\nprivate let stack = [\n    MemberOutput(name: \"camera\", p: 0.42, verdict: \"real\", fields: [Field(\"p_neutral\", .number(0.2))]),\n    MemberOutput(name: \"capture\", p: nil, verdict: \"absent\", fields: [Field(\"peak\", .number(7)), Field(\"valid\", .flag(true)), Field(\"present\", .flag(false))]),\n    MemberOutput(name: \"semantic-tiles\", p: 0.5, verdict: \"real\", fields: [Field(\"majority\", .number(0.5)), Field(\"grid\", .grid([[0.99, 0.0]]))]),\n]\nprivate let revisions = [\n    RevisionRecord(name: \"combiner\", applied: true, p: 0.91, prediction: \"generated\",\n                   fields: [Field(\"anchor\", .text(\"camera\")), Field(\"pooled\", .number(0.91)), Field(\"influence\", .map([\"art\": 1.5]))]),\n    RevisionRecord(name: \"frame-seam\", applied: false, p: 0.91, prediction: \"generated\", fields: [Field(\"interior_p\", .absent)]),\n]\nprivate let hashes = BundleHashes(manifestSHA256: \"cc\", artifacts: [\"camera\": \"aa\", \"combiner\": \"bb\"])\n\nprivate func result(bundle: BundleHashes? = hashes) -> InferenceResult {\n    InferenceResult(prediction: \"generated\", p: 0.91, threshold: 0.5, band: 0.04, imageWidth: 640, imageHeight: 480,\n                    stack: stack, revisions: revisions, bundle: bundle)\n}\n\n@Suite(\"Result JSON\")\nstruct ResultJSONTests {\n    @Test(\"the JSON writes exactly the schema-v1 keys\")\n    func jsonV1() throws {\n        let json = try object(ResultJSON.encode(result(), times: [], device: \"route\"))\n        #expect(Set(json.keys) == [\"bundle\", \"device\", \"image\", \"revisions\", \"schema_version\", \"stack\", \"times_sec\", \"verdict\"])\n        #expect(json[\"schema_version\"] as? Int == 1 && json[\"device\"] as? String == \"route\")\n        let verdict = try #require(json[\"verdict\"] as? [String: Any])\n        #expect(Set(verdict.keys) == [\"band\", \"p\", \"prediction\", \"threshold\"])\n        #expect(verdict[\"prediction\"] as? String == \"generated\" && abs((verdict[\"p\"] as? Double ?? 0) - 0.91) < 1e-6)\n        #expect((json[\"image\"] as? [String: Any])?[\"width\"] as? Int == 640)\n        let bundle = try #require(json[\"bundle\"] as? [String: Any])\n        #expect(Set(bundle.keys) == [\"artifacts\", \"manifest_sha256\"] && (bundle[\"artifacts\"] as? [String: String])?[\"camera\"] == \"aa\")\n    }\n\n    @Test(\"a member is its name, p and verdict beside its own fields; a revision its name, applied, p and prediction beside its own\")\n    func membersAndRevisions() throws {\n        let json = try object(ResultJSON.encode(result(), times: [], device: \"route\"))\n        let members = try #require(json[\"stack\"] as? [[String: Any]])\n        #expect(members.map { $0[\"name\"] as? String } == [\"camera\", \"capture\", \"semantic-tiles\"])\n        #expect(Set(members[0].keys) == [\"name\", \"p\", \"verdict\", \"p_neutral\"] && abs((members[0][\"p_neutral\"] as? Double ?? 0) - 0.2) < 1e-6)\n        #expect(members[1][\"p\"] is NSNull && members[1][\"present\"] as? Bool == false)\n        #expect((members[2][\"grid\"] as? [[Double]])?.first?.first.map { abs($0 - 0.99) < 1e-6 } == true)\n        let records = try #require(json[\"revisions\"] as? [[String: Any]])\n        #expect(Set(records[0].keys) == [\"name\", \"applied\", \"p\", \"prediction\", \"anchor\", \"pooled\", \"influence\"])\n        #expect(records[0][\"anchor\"] as? String == \"camera\" && (records[0][\"influence\"] as? [String: Double])?[\"art\"] == 1.5)\n        #expect(records[1][\"applied\"] as? Bool == false && records[1][\"interior_p\"] is NSNull)\n    }\n\n    @Test(\"a result without a bundle omits that block, and the same result writes the same bytes\")\n    func jsonOmitsBundle() throws {\n        let bare = result(bundle: nil)\n        let json = try object(ResultJSON.encode(bare, times: [0.5], device: \"gpu\"))\n        #expect(Set(json.keys) == [\"device\", \"image\", \"revisions\", \"schema_version\", \"stack\", \"times_sec\", \"verdict\"])\n        #expect(try ResultJSON.encode(bare, times: [0.5], device: \"gpu\") == ResultJSON.encode(bare, times: [0.5], device: \"gpu\"))\n    }\n\n    @Test(\"a member reads its fields back by key, and the stack finds a member by name\")\n    func accessors() {\n        #expect(stack.member(\"capture\")?.flag(\"valid\") == true && stack.member(\"camera\")?.number(\"p_neutral\") == 0.2)\n        #expect(stack.member(\"semantic-tiles\")?.grid(\"grid\") == [[0.99, 0.0]] && stack.member(\"art\") == nil)\n        #expect(revisions.revision(\"combiner\")?.text(\"anchor\") == \"camera\")\n    }\n\n    @Test(\"only the control profile commits a semantic probe\")\n    func semanticProfiles() {\n        let control = PublicSurface.project(profile: .control, originalP: 0.20, originalVerdict: \"real\", probeP: 0.90, probeVerdict: \"generated\", probeDecisive: true)\n        #expect(control == SemanticProjection(p: 0.90, verdict: \"generated\", decisive: true))\n        for profile in [SemanticResponsibility.semanticDiagnosticOnly, .semanticRemoved] {\n            let projected = PublicSurface.project(profile: profile, originalP: 0.20, originalVerdict: \"real\", probeP: 0.90, probeVerdict: \"generated\", probeDecisive: true)\n            #expect(projected == SemanticProjection(p: 0.20, verdict: \"real\", decisive: false))\n        }\n    }\n\n    @Test(\"the semantic profiles' raw values are stable and round-trip\")\n    func rawValues() throws {\n        #expect(SemanticResponsibility.semanticDiagnosticOnly.rawValue == \"semantic_diagnostic_only\")\n        #expect(SemanticResponsibility.semanticRemoved.rawValue == \"semantic_removed\")\n        #expect(try JSONDecoder().decode(SemanticResponsibility.self, from: JSONEncoder().encode(SemanticResponsibility.semanticRemoved)) == .semanticRemoved)\n    }\n}\n\n@Suite(\"Route batch manifest\")\nstruct RouteBatchTests {\n    @Test(\"parses order exactly\")\n    func parses() throws {\n        let items = try RouteBatch.parse(Data(\"\"\"\n        {\"id\":\"first\",\"path\":\"/a.jpg\"}\n        {\"id\":\"second\",\"path\":\"/b.png\"}\n        \"\"\".utf8))\n        #expect(items.map(\\.id) == [\"first\", \"second\"] && items.map(\\.path) == [\"/a.jpg\", \"/b.png\"])\n    }\n\n    @Test(\"rejects a duplicate id before inference\")\n    func duplicate() {\n        #expect(throws: RouteBatchError.duplicateID(line: 2, id: \"same\")) {\n            try RouteBatch.parse(Data(\"\"\"\n            {\"id\":\"same\",\"path\":\"/a.jpg\"}\n            {\"id\":\"same\",\"path\":\"/b.jpg\"}\n            \"\"\".utf8))\n        }\n    }\n\n    @Test(\"rejects a bad id or shape, a hint among them\")\n    func rejects() {\n        #expect(throws: RouteBatchError.self) { try RouteBatch.parse(Data(#\"{\"id\":\"bad id \",\"path\":\"/a\"}\"#.utf8)) }\n        #expect(throws: RouteBatchError.self) { try RouteBatch.parse(Data(#\"{\"id\":\"a\",\"path\":\"/a\",\"hint\":\"camera\"}\"#.utf8)) }\n        #expect(throws: RouteBatchError.self) { try RouteBatch.parse(Data(#\"{\"id\":\"a\"}\"#.utf8)) }\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/SafetensorsLayoutTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,54]],"header":{"lines":[1,10],"target":"VeilGardeCoreTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1351,"scopes":[["S","SafetensorsLayoutTests",null,"",16,17,[17,30],54,null,-1,0,"a"],["f","fixture",[],"",18,19,[19,26],35,null,0,0,"a"],["f","shipped",["_"],"static",38,38,[38,48],43,[37,37],0,0,"a"],["f","shippedFiles",["_"],"",45,46,[46,45],53,null,0,0,"a"]],"old":"","new":"//\n//  SafetensorsLayoutTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The writer's python layout writes the bytes Python's safetensors writes: a committed\n//        file from safetensors 0.5 (six dtypes) is reproduced exactly, and so, when this Mac\n//        has them, are the shipped weight files exported from Python (the noiseprint and DINOv2-small),\n//        re-encoded from their own tensors. That is what lets an import be byte-identical.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n\n@Suite(\"Safetensors: Python's own layout\")\nstruct SafetensorsLayoutTests {\n    @Test(\"a file Python's safetensors wrote is reproduced byte for byte\")\n    func fixture() throws {\n        let entries: [SafetensorsWriter.Entry] = [\n            .init(\"b_u8\", shape: [5], .uint8([0, 1, 127, 254, 255])),\n            .init(\"s_i16\", shape: [2], .int16([-300, 300])),\n            .init(\"h_f16\", shape: [3], .float16Bits([0x3C00, 0xC000, 0x3800])),\n            .init(\"m_i32\", shape: [1], .int32([-7])),\n            .init(\"a_u32\", shape: [2], .uint32([1, 4_294_967_295])),\n            .init(\"z_f32\", shape: [1], .float32([-0.0])),\n            .init(\"w_f32\", shape: [2, 3], .float32([0, 1.5, -2, 3.25, 1e-3, 7])),\n        ]\n        let expected = try Data(contentsOf: Fixture.url(\"python_layout.safetensors\"))\n        #expect(try SafetensorsWriter.encode(entries, layout: .python) == expected)\n        #expect(try SafetensorsWriter.encode(entries.reversed(), layout: .python) == expected, \"the order the entries come in does not matter\")\n        let read = try SafetensorsFile(data: expected)\n        #expect(try read.uint32(\"a_u32\") == [1, 4_294_967_295])\n        #expect(try read.bytes(\"b_u8\") == Data([0, 1, 127, 254, 255]))\n    }\n\n    /// A shipped weight file exported with Python's safetensors, when this Mac has one.\n    static func shipped(_ name: String) -> URL? {\n        var folders: [URL] = []\n        if let named = ProcessInfo.processInfo.environment[\"VEILGARDE_WEIGHTS\"] { folders.append(URL(fileURLWithPath: named)) }\n        if let area = WorkArea.resolve() { folders.append(area.weights) }\n        return folders.map { $0.appendingPathComponent(name) }.first { FileManager.default.fileExists(atPath: $0.path) }\n    }\n\n    @Test(\"the shipped weights re-encode to their own bytes\", arguments: [\"noiseprint_v1.safetensors\", \"dinov2_small.safetensors\"])\n    func shippedFiles(_ name: String) throws {\n        guard let url = Self.shipped(name) else { return }\n        let file = try SafetensorsFile(url: url)\n        let entries = try file.names.map { SafetensorsWriter.Entry($0, shape: try file.tensor($0).shape, .float32(try file.float32($0))) }\n        let data = try SafetensorsWriter.encode(entries, layout: .python)\n        #expect(data.count == file.data.count)\n        #expect(data == file.data, \"\\(name) re-encoded differs from the file\")\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/StoreTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,126]],"header":{"lines":[1,10],"target":"VeilGardeCoreTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1355,"scopes":[["S","StoreTests",null,"",16,17,[17,18],126,null,-1,0,"a"],["f","tempDirectory",[],"",18,18,[18,39],22,null,0,0,"a"],["f","shard",["_","ids","label"],"",24,24,[24,74],31,null,0,0,"a"],["f","roundTrip",[],"",33,34,[34,28],45,null,0,0,"a"],["f","selection",[],"",47,48,[48,28],67,null,0,0,"a"],["f","readsSeedStore",[],"",69,70,[70,33],77,null,0,0,"a"],["f","olderShard",["_","name"],"",81,81,[81,77],97,[79,80],0,0,"a"],["f","olderRefused",[],"",99,100,[100,31],108,null,0,0,"a"],["f","migration",[],"",110,111,[111,28],125,null,0,0,"a"]],"old":"","new":"//\n//  StoreTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The features-only store: a v1 shard round-trips its rows and columns and is never\n//        overwritten; a shard of an older format is refused with the migrate hint, and the\n//        migration rewrites it whole (the same rows, the three columns' bytes, the rest left\n//        behind); a selection filters, keeps or drops duplicates, and stacks the camera row.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Feature store\")\nstruct StoreTests {\n    func tempDirectory() throws -> URL {\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-store-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n        return dir\n    }\n\n    func shard(_ name: String, ids: [String], label: Int) -> FeatureShard {\n        let rows = ids.map { FeatureRow(id: $0, path: \"/x/\\($0).jpg\", label: label, category: \"art\", source: \"test\") }\n        var columns: [FeatureColumn: [Float]] = [:]\n        for column in FeatureColumn.allCases {\n            columns[column] = (0..<(ids.count * column.width)).map { Float($0) + (label == 1 ? 0.5 : 0) }\n        }\n        return FeatureShard(name: name, rows: rows, columns: columns, metadata: [\"dino_variant\": \"small\"])\n    }\n\n    @Test(\"a shard round-trips and is never overwritten\")\n    func roundTrip() throws {\n        let dir = try tempDirectory()\n        defer { try? FileManager.default.removeItem(at: dir) }\n        let written = shard(\"s1\", ids: [\"a\", \"b\", \"c\"], label: 1)\n        try written.write(to: dir)\n        let read = try FeatureShard.read(\"s1\", in: dir)\n        #expect(read.rows == written.rows)\n        #expect(read.columns == written.columns)\n        #expect(read.metadata[\"format\"] == FeatureShard.format && read.metadata[\"dino_variant\"] == \"small\")\n        #expect(Array(read.vector(.cap, row: 1)) == (9..<18).map { Float($0) + 0.5 })\n        #expect(throws: VeilGardeFailure.self) { try written.write(to: dir) }\n    }\n\n    @Test(\"a selection keeps duplicates as the Python store does, dedups on request, filters, and stacks the camera row\")\n    func selection() throws {\n        let dir = try tempDirectory()\n        defer { try? FileManager.default.removeItem(at: dir) }\n        try shard(\"a_first\", ids: [\"x\", \"y\"], label: 1).write(to: dir)\n        try shard(\"b_second\", ids: [\"y\", \"z\"], label: 0).write(to: dir)\n        let store = FeatureStore(directory: dir)\n        #expect(store.shardNames() == [\"a_first\", \"b_second\"])\n        #expect(try store.select(columns: [.cap]).rows.map(\\.id) == [\"x\", \"y\", \"y\", \"z\"])\n        let all = try store.select(columns: Set(FeatureColumn.allCases), dedup: true)\n        #expect(all.rows.map(\\.id) == [\"x\", \"y\", \"z\"])\n        #expect(all.shards == [\"a_first\", \"a_first\", \"b_second\"])\n        let camera = all.matrix(CameraRow.columns)\n        #expect(camera.count == 3 * 393)\n        #expect(camera[0] == 0.5)                 // x's first dino_fusion value\n        #expect(camera[384] == 0.5)               // x's first capture value\n        #expect(camera[393 * 2] == 384)           // z's first dino_fusion value (row 1 of b_second)\n        let reals = all.filter { !$0.isGenerated }\n        #expect(reals.rows.map(\\.id) == [\"z\"])\n        #expect(try store.ids() == [\"x\", \"y\", \"z\"])\n    }\n\n    @Test(\"the work area's store reads as v1 shards\", .enabled(if: FileManager.default.fileExists(atPath: Fixture.seedStore.appendingPathComponent(\"ai_video_0711_meta.json\").path)))\n    func readsSeedStore() throws {\n        let shard = try FeatureShard.read(\"ai_video_0711\", in: Fixture.seedStore)\n        #expect(shard.count == 112)\n        #expect(shard.columns[.dinoNorm]?.count == 112 * 384)\n        #expect(shard.columns[.cap]?.count == 112 * 9)\n        #expect(shard.rows.allSatisfy { $0.label == 1 && $0.id.count == 40 })\n        #expect(shard.metadata[\"format\"] == FeatureShard.format)\n    }\n\n    /// A shard as the seed store and the older format wrote it: no format in the header, the\n    /// retired tensors beside the kept ones, a row key the store no longer reads.\n    func olderShard(_ dir: URL, name: String = \"old\") throws -> FeatureShard {\n        let rows = [FeatureRow(id: \"a\", path: \"/a.jpg\", label: 1, category: \"art\", source: \"s\"), FeatureRow(id: \"b\", path: \"/b.jpg\", label: 0, category: \"photo\", source: \"s\")]\n        var meta = try JSONSerialization.jsonObject(with: JSONEncoder().encode(rows)) as! [[String: Any]]\n        meta[0][\"warp_model\"] = \"516119c92d36\"\n        try JSONSerialization.data(withJSONObject: meta).write(to: FeatureShard.metaURL(dir, name))\n        var entries: [SafetensorsWriter.Entry] = []\n        var columns: [FeatureColumn: [Float]] = [:]\n        for column in FeatureColumn.allCases {\n            let values = (0..<(2 * column.width)).map { Float($0) * 0.25 }\n            columns[column] = values\n            entries.append(.init(column.rawValue, shape: [2, column.width], .float32(values)))\n        }\n        entries.append(.init(\"warp\", shape: [2, 4], .float32([1, 2, 3, 4, 5, 6, 7, 8])))\n        entries.append(.init(\"noiseprint\", shape: [2, 2], .float32([1, 2, 3, 4])))\n        try SafetensorsWriter.write(entries, to: FeatureShard.tensorsURL(dir, name))\n        return FeatureShard(name: name, rows: rows, columns: columns)\n    }\n\n    @Test(\"a shard of an older format is refused with the migrate hint\")\n    func olderRefused() throws {\n        let dir = try tempDirectory()\n        defer { try? FileManager.default.removeItem(at: dir) }\n        _ = try olderShard(dir)\n        #expect(throws: VeilGardeFailure.self) { try FeatureShard.read(\"old\", in: dir) }\n        do { _ = try FeatureShard.read(\"old\", in: dir) } catch let failure as VeilGardeFailure {\n            #expect(failure.description.contains(\"store migrate\"))\n        }\n    }\n\n    @Test(\"the migration rewrites a shard whole: the same rows, the three columns' bytes, the rest left behind; it never overwrites\")\n    func migration() throws {\n        let dir = try tempDirectory()\n        defer { try? FileManager.default.removeItem(at: dir) }\n        let old = dir.appendingPathComponent(\"old\", isDirectory: true), new = dir.appendingPathComponent(\"new\", isDirectory: true)\n        try FileManager.default.createDirectory(at: old, withIntermediateDirectories: true)\n        let expected = try olderShard(old)\n        let reports = try StoreMigration.migrate(from: old, to: new)\n        #expect(reports.count == 1 && reports[0].equal && reports[0].rowsIn == 2 && reports[0].rowsOut == 2)\n        #expect(Set(reports[0].left) == [\"noiseprint\", \"warp\"] && reports[0].columns.count == 3)\n        let read = try FeatureShard.read(\"old\", in: new)\n        #expect(read.rows == expected.rows && read.columns == expected.columns && read.metadata[\"format\"] == FeatureShard.format)\n        let meta = try String(contentsOf: FeatureShard.metaURL(new, \"old\"), encoding: .utf8)\n        #expect(!meta.contains(\"warp_model\"), \"a row key the store no longer reads is not written back\")\n        #expect(throws: VeilGardeFailure.self) { try StoreMigration.migrate(from: old, to: new) }\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/SupportTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,101]],"header":{"lines":[1,9],"target":"VeilGardeCoreTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1364,"scopes":[["S","SupportTests",null,"",15,16,[16,20],101,null,-1,0,"a"],["S","Sample",null,"",17,17,[17,38],17,null,0,8,"a"],["f","stableJSON",[],"",19,20,[20,29],26,null,0,0,"a"],["f","hashes",[],"",28,29,[29,18],32,null,0,0,"a"],["f","safetensorsRoundTrip",[],"",34,35,[35,39],55,null,0,0,"a"],["f","stableSplit",[],"",57,58,[58,23],65,null,0,0,"a"],["f","splitMix",[],"",67,68,[68,20],76,null,0,0,"a"],["f","toml",[],"",78,79,[79,23],91,null,0,0,"a"],["f","workArea",[],"",93,94,[94,20],100,null,0,0,"a"]],"old":"","new":"//\n//  SupportTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The support layer's promises: stable JSON bytes, known hash vectors, safetensors that\n//        round-trip every dtype and write the same bytes twice, splits that never move, a seeded\n//        generator that replays, and the recipe TOML subset.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Support\")\nstruct SupportTests {\n    struct Sample: Codable, Equatable { var b: Int; var a: String; var nan: Double }\n\n    @Test(\"JSON encodes sorted keys and the same bytes every time\")\n    func stableJSON() throws {\n        let value = Sample(b: 2, a: \"x/y\", nan: .nan)\n        let one = try JSONCoding.line(value)\n        #expect(one == #\"{\"a\":\"x/y\",\"b\":2,\"nan\":\"nan\"}\"#)\n        #expect(try JSONCoding.line(value) == one)\n        #expect(JSONCoding.standardized(#\"{\"v\": NaN, \"s\": \"NaN\"}\"#) == #\"{\"v\": \"nan\", \"s\": \"NaN\"}\"#)\n    }\n\n    @Test(\"SHA-256 and SHA-1 match their published vectors\")\n    func hashes() {\n        #expect(ContentHash.sha256Hex(\"abc\") == \"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\")\n        #expect(ContentHash.sha1Hex(Data(\"abc\".utf8)) == \"a9993e364706816aba3e25717850c26c9cd0d89d\")\n    }\n\n    @Test(\"safetensors round-trip every dtype and write identical bytes\")\n    func safetensorsRoundTrip() throws {\n        let entries = [\n            SafetensorsWriter.Entry(\"z_f32\", shape: [2, 3], .float32([0, 1.5, -2, .infinity, 3e-38, 7])),\n            SafetensorsWriter.Entry(\"a_i32\", shape: [3], .int32([-1, 0, Int32.max])),\n            SafetensorsWriter.Entry(\"m_i16\", shape: [2], .int16([-7, 300])),\n            SafetensorsWriter.Entry(\"u_u8\", shape: [4], .uint8([0, 1, 254, 255])),\n            SafetensorsWriter.Entry(\"h_f16\", shape: [2], .float16Bits([0x3C00, 0xC000])),\n        ]\n        let data = try SafetensorsWriter.encode(entries, metadata: [\"format\": \"test-v1\", \"b\": \"2\"])\n        #expect(try SafetensorsWriter.encode(entries.reversed(), metadata: [\"b\": \"2\", \"format\": \"test-v1\"]) == data)\n        let file = try SafetensorsFile(data: data)\n        #expect(file.metadata == [\"format\": \"test-v1\", \"b\": \"2\"])\n        #expect(try file.float32(\"z_f32\") == [0, 1.5, -2, .infinity, 3e-38, 7])\n        #expect(try file.tensor(\"z_f32\").shape == [2, 3])\n        #expect(try file.int32(\"a_i32\") == [-1, 0, Int32.max])\n        #expect(try file.int16(\"m_i16\") == [-7, 300])\n        #expect(try file.uint8(\"u_u8\") == [0, 1, 254, 255])\n        #expect(try file.float32(\"h_f16\") == [1, -2])\n        let headerLength = data.withUnsafeBytes { Int(UInt64(littleEndian: $0.loadUnaligned(as: UInt64.self))) }\n        #expect((8 + headerLength) % 8 == 0)\n    }\n\n    @Test(\"a split assignment never moves and its fractions hold\")\n    func stableSplit() {\n        #expect(StableSplit.unit(\"IMG_0291\", salt: \"split:v1\") == StableSplit.unit(\"IMG_0291\", salt: \"split:v1\"))\n        #expect(StableSplit.unit(\"IMG_0291\", salt: \"split:v1\") != StableSplit.unit(\"IMG_0291\", salt: \"platt:v1\"))\n        var counts: [Partition: Int] = [:]\n        for i in 0..<10_000 { counts[StableSplit.partition(\"stem-\\(i)\", salt: \"split:v1\", train: 0.70, val: 0.15), default: 0] += 1 }\n        #expect(abs(Double(counts[.train] ?? 0) / 10_000 - 0.70) < 0.02)\n        #expect(abs(Double(counts[.val] ?? 0) / 10_000 - 0.15) < 0.02)\n    }\n\n    @Test(\"SplitMix64 replays its sequence and shuffles every index once\")\n    func splitMix() {\n        var a = SplitMix64(seed: 42)\n        var b = SplitMix64(seed: 42)\n        #expect((0..<8).map { _ in a.next() } == (0..<8).map { _ in b.next() })\n        var c = SplitMix64(seed: 7)\n        #expect(Set(c.permutation(100)) == Set(0..<100))\n        var d = SplitMix64(seed: 1)\n        #expect((0..<1000).allSatisfy { _ in (0..<1).contains(d.unit()) })\n    }\n\n    @Test(\"the recipe TOML subset parses tables, values and comments\")\n    func toml() throws {\n        let document = try TOMLSubset.parse(\"\"\"\n        id = \"shipped\" # the recipe\n        [warp]\n        trees = 200\n        eta = 0.05\n        heads = [\"art\", \"blur\"]\n        \"\"\")\n        #expect(TOMLSubset.value(document, \"\", \"id\")?.string == \"shipped\")\n        #expect(TOMLSubset.value(document, \"warp\", \"trees\")?.integer == 200)\n        #expect(TOMLSubset.value(document, \"warp\", \"eta\")?.float == 0.05)\n        #expect(TOMLSubset.value(document, \"warp\", \"heads\")?.strings == [\"art\", \"blur\"])\n    }\n\n    @Test(\"the work area is the one the environment names, else none; the datasets theirs, else the work area's\")\n    func workArea() {\n        #expect(WorkArea.resolve(environment: [\"VEILGARDE_WORK_AREA\": \"/tmp/vg-area\"])?.root.path == \"/tmp/vg-area\")\n        #expect(WorkArea.resolve(environment: [:]) == nil && WorkArea.resolve(environment: [\"VEILGARDE_WORK_AREA\": \"\"]) == nil)\n        #expect(WorkArea.datasets(environment: [\"VEILGARDE_WORK_AREA\": \"/tmp/vg-area\"])?.path == \"/tmp/vg-area/datasets\")\n        #expect(WorkArea.datasets(environment: [\"VEILGARDE_WORK_AREA\": \"/tmp/vg-area\", \"VEILGARDE_DATASETS\": \"/data\"])?.path == \"/data\")\n        #expect(WorkArea.datasets(environment: [:]) == nil)\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/VerdictTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,38]],"header":{"lines":[1,8],"target":"VeilGardeCoreTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1373,"scopes":[["S","VerdictTests",null,"",14,15,[15,20],38,null,-1,0,"a"],["f","labels",[],"",16,17,[17,18],25,null,0,0,"a"],["f","featureOrder",[],"",27,28,[28,31],37,null,0,0,"a"]],"old":"","new":"//\n//  VerdictTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The three-state label's open band at the camera member's operating point, and the camera\n//        head's 393-column order: DINOv2 then the nine capture values.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Verdict and the camera row\")\nstruct VerdictTests {\n    @Test(\"the band is open and generated is strictly above the threshold\")\n    func labels() {\n        let rule = DecisionRule.camera\n        #expect(rule.threshold == 0.5 && rule.band == 0.04)\n        #expect(rule.label(0.5) == \"inconclusive\")\n        #expect(rule.label(0.53) == \"inconclusive\")\n        #expect(rule.label(0.54) == \"generated\")   // exactly the band edge is decisive\n        #expect(rule.label(0.45) == \"real\")\n        #expect(rule.label(0.9) == \"generated\")\n    }\n\n    @Test(\"the camera row keeps its trained column order: DINOv2 (384), then capture (9)\")\n    func featureOrder() throws {\n        let capture = CaptureFeatures(vector: [42, 1, 1, 1024, 3, 0.4, 0.5, 0.1, 0.2])\n        #expect(capture.signature == CaptureSignature(peak: 42, valid: true, nativePixels: 1024, present: true))\n        let row = CameraRow(dino: [Float](repeating: 0.5, count: 384), capture: capture)\n        let flat = row.asVector\n        #expect(flat.count == 393 && CameraRow.width == 393)\n        #expect(flat[0] == 0.5 && flat[383] == 0.5 && flat[384] == 42 && flat[387] == 1024 && flat[392] == 0.2)\n        #expect(CameraRow.names.count == 393 && CameraRow.names[384] == \"cap_\" + CaptureFeatures.names[0])\n        #expect(CameraRow.columns == [.dinoFusion, .cap] && CameraRow.columns.map(\\.width).reduce(0, +) == CameraRow.width)\n    }\n}\n"}]};
